import subprocess
import psutil
import time
import os

def task_func(script_path: str, timeout=10) -> dict:
    if not os.path.exists(script_path):
        return {'CPU Usage': 0.0, 'Memory Usage': 0}

    process = subprocess.Popen(['bash', script_path])
    try:
        ps_process = psutil.Process(process.pid)
    except psutil.NoSuchProcess:
        return {'CPU Usage': 0.0, 'Memory Usage': 0}

    total_cpu = 0.0
    total_memory = 0
    start_time = time.time()

    while process.poll() is None:
        elapsed_time = time.time() - start_time
        if elapsed_time > timeout:
            process.terminate()
            process.wait()
            break

        try:
            total_cpu += ps_process.cpu_percent(interval=None)
            total_memory += ps_process.memory_info().rss
        except (psutil.NoSuchProcess, psutil.ZombieProcess):
            break

        time.sleep(0.1)

    if process.poll() is None:
        process.terminate()
        process.wait()

    return {'CPU Usage': total_cpu, 'Memory Usage': total_memory}
